const executedStage = function () {
  for (let i = 0; i < STAGE_ORDER.length; i++) {
    if (nodeExecuted(STAGE_ORDER[i])) return STAGE_ORDER[i];
  }
  for (let i = 0; i < CODE_NODES.length; i++) {
    if (nodeExecuted(CODE_NODES[i])) return CODE_NODES[i];
  }
  return null;
};

const canonicalStage = function (name) {
  if (name === null) return null;
  const alias = STAGE_ALIAS[name];
  return (typeof alias === 'string') ? alias : name;
};
const src = canonicalStage(executedStage());

// n8n keeps the transport error on the error output; the backend body is sometimes embedded in it
// as raw text. Only the technical codes are inspected, never a field value.
const transportText = function () {
  const texts = [];
  if (typeof incoming.error === 'string') texts.push(incoming.error);
  if (incoming.error !== null && typeof incoming.error === 'object') {
    if (typeof incoming.error.message === 'string') texts.push(incoming.error.message);
    if (typeof incoming.error.description === 'string') texts.push(incoming.error.description);
  }
  return texts.join(' ');
};

const httpStatus = function () {
  const found = [];
  const push = function (value) {
    if (value !== undefined && value !== null) found.push(value);
  };
  push(incoming.statusCode);
  push(incoming.httpCode);
  if (incoming.error !== null && typeof incoming.error === 'object') {
    push(incoming.error.statusCode);
    push(incoming.error.httpCode);
  }
  for (let i = 0; i < found.length; i++) {
    const n = Number(found[i]);
    if (Number.isInteger(n) && n >= 100 && n <= 599) return n;
  }
  const text = transportText();
  const patterns = [/^\s*([1-5][0-9][0-9])(\s|-|\/|$)/, /status code ([1-5][0-9][0-9])/i];
  for (let i = 0; i < patterns.length; i++) {
    const found2 = text.match(patterns[i]);
    if (found2) return Number(found2[1]);
  }
  return null;
};

const isHttpErrorItem = function () {
  if (incoming.error !== undefined && incoming.error !== null) return true;
  const status = httpStatus();
  return status !== null && status >= 400;
};

const shapes = function () {
  const list = [incoming];
  const text = transportText();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try {
      const parsed = JSON.parse(text.slice(start, end + 1));
      if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) list.push(parsed);
    } catch (e) {
      // transport message is not JSON: the item itself stays the only source
    }
  }
  return list;
};

const bodies = shapes();

const pick = function (key) {
  for (let i = 0; i < bodies.length; i++) {
    const value = bodies[i][key];
    if (value !== undefined && value !== null) return value;
  }
  return undefined;
};

const pickString = function (key) {
  const value = pick(key);
  return typeof value === 'string' && value !== '' ? value : null;
};

const pickArray = function (key) {
  const value = pick(key);
  return Array.isArray(value) ? value : null;
};

const codeList = function (key) {
  const list = pickArray(key);
  const codes = [];
  if (list === null) return codes;
  for (let i = 0; i < list.length; i++) {
    const entry = list[i];
    if (typeof entry === 'string') codes.push(entry);
    else if (entry !== null && typeof entry === 'object' && typeof entry.code === 'string') codes.push(entry.code);
  }
  return codes;
};

const technicalCode = function () {
  for (let i = 0; i < bodies.length; i++) {
    const body = bodies[i];
    if (body.error !== null && typeof body.error === 'object' && typeof body.error.code === 'string') return body.error.code;
    if (typeof body.errorCode === 'string') return body.errorCode;
    if (typeof body.code === 'string') return body.code;
  }
  return null;
};

// 3.2 single E8 400 discrimination rule: ERR_DOCUMENT_TYPE_NON_SUPPORTE is the only 200 outcome of
// an E8 rejection; it is looked up in errors[], fieldErrors[], the technical code and the transport
// message so the rule holds whatever shape n8n gives to the error output.
const hasUnsupportedCode = function () {
  if (codeList('errors').indexOf(UNSUPPORTED_CODE) !== -1) return true;
  if (codeList('fieldErrors').indexOf(UNSUPPORTED_CODE) !== -1) return true;
  if (technicalCode() === UNSUPPORTED_CODE) return true;
  return transportText().indexOf(UNSUPPORTED_CODE) !== -1;
};

const requestIdOf = function (source) {
  const value = (source !== null && source !== undefined && typeof source.requestId === 'string')
    ? source.requestId
    : pickString('requestId');
  return (typeof value === 'string' && REQUEST_ID_RE.test(value)) ? value : null;
};

// requestId is echoed only when the request is known to be persisted (3.1 / 3.3).
const persistedRequestId = function () {
  const value = requestIdOf(null);
  if (value === null) return null;
  if (PERSISTED_STAGES.indexOf(src) !== -1) return value;
  if (pickString('status') !== null) return value;
  return null;
};

const isStructuralRejection = function () {
  const codes = codeList('fieldErrors');
  if (codes.length === 0) return false;
  for (let i = 0; i < codes.length; i++) {
    if (STRUCTURAL_FIELD_CODES.indexOf(codes[i]) === -1) return false;
  }
  return true;
};

const verbatimStatus = function () {
  return pickString('status');
};

const verbatimCause = function () {
  for (let i = 0; i < bodies.length; i++) {
    if (typeof bodies[i].cause === 'string' && bodies[i].cause !== '') return bodies[i].cause;
  }
  const code = technicalCode();
  if (code !== null && GENERATION_CAUSES.indexOf(code) !== -1) return code;
  return null;
};

// 3.3 MISSING_INFORMATION: fixed FR template built from the field KEYS only (never their values).
const missingFieldKeys = function () {
  const missing = pickArray('missingFields');
  const keys = [];
  if (missing === null) return keys;
  for (let i = 0; i < missing.length; i++) {
    if (typeof missing[i] === 'string' && FIELD_KEY_RE.test(missing[i])) keys.push(missing[i]);
  }
  return keys;
};

// Generation metadata comes from GenerateDocumentResponse (E5); E6 only proves servability and its
// DOCX body is never read. A documents[] window keeps the most recent generatedAt only (3.3).
// Generation metadata is READ, never produced: GenerateDocumentResponse (E5, 201) first, then the
// documents[] entry selected by AdoptE2Reconcile when the decision came from an E2 read (R3:
// GENERATED requires E5 201 OR E2 GENERATED, and E6 200). The response body of the verification
// stage is never read: this node only reads Code-node and HTTP metadata items. In a documents[]
// window (F-I-9) only the most recent entry (generatedAt max) is used, so exactly ONE documentId
// is ever exposed (3.3).
const generationPayload = function () {
  // On the R2 recovery path E5RetryGenerate ran AFTER the failed E5GenerateDocument, so its 201
  // is the only valid source of generation metadata (a failed call carries none).
  const retry = nodeJson('E5RetryGenerate');
  if (typeof retry.documentId === 'string' && retry.documentId !== '') return retry;
  const e5 = nodeJson('E5GenerateDocument');
  if (typeof e5.documentId === 'string' && e5.documentId !== '') return e5;
  const adopted = nodeJson('AdoptE2Reconcile');
  if (typeof adopted.documentId === 'string' && adopted.documentId !== '') return adopted;
  return {};
};

// 3.3 GENERATED requires documentId, fileName, downloadPath and generatedAt. If the backend read did
// not supply them all, GENERATED is NOT declared: ERROR instead of a guessed success (R3).
const generationMetadataComplete = function (g) {
  if (g === null || typeof g !== 'object') return false;
  if (typeof g.documentId !== 'string' || !DOCUMENT_ID_RE.test(g.documentId)) return false;
  if (typeof g.fileName !== 'string' || g.fileName === '') return false;
  if (typeof g.generatedAt !== 'string' || g.generatedAt === '') return false;
  if (typeof g.downloadPath !== 'string' || g.downloadPath === '') return false;
  return true;
};

// Faults detected by the orchestration Code nodes themselves (asset/configuration, strict JSON
// decode of the LLM answer). They outrank any later HTTP failure they may have triggered.
const orchestratorFailure = function () {
  for (let i = 0; i < CODE_NODES.length; i++) {
    const item = nodeJson(CODE_NODES[i]);
    if (item.outcome === 'ERROR') {
      const code = (item.error !== null && typeof item.error === 'object' && typeof item.error.code === 'string')
        ? item.error.code
        : (typeof item.errorCode === 'string' ? item.errorCode : null);
      return (code !== null && APPROVED_ERROR_CODES.indexOf(code) !== -1) ? code : 'INTERNAL_ERROR';
    }
  }
  return null;
};

const classifyOutcome = function () {
  // (1) Branch marker written by the ingress gate only (CheckClarificationBound).
  if (incoming.__branch === 'CLARIFICATION_LIMIT_REACHED') return 'CLARIFICATION_LIMIT_REACHED';
  // (2) The item already carries an approved outcome: ingress rejection (INVALID_REQUEST) or
  // orchestration fault routed directly to this node by the C5 short-circuits (ERROR). No HTTP node
  // is reached after such a fault, so nothing technical can precede it.
  if (typeof incoming.outcome === 'string' && APPROVED_OUTCOMES.indexOf(incoming.outcome) !== -1) return incoming.outcome;
  // (3) A fault raised by another orchestration Code node outranks anything a downstream stage reports.
  if (orchestratorFailure() !== null) return 'ERROR';

  // (4) TECHNICAL EVIDENCE, read before any business field (C4: the transport/technical failure takes
  // precedence; a 200-class outcome must never be emitted for an error-output item or a 4xx/5xx).
  const transportFailure = isHttpErrorItem();
  const http = httpStatus();
  const code = technicalCode();
  const receivedFailure = transportFailure || (http !== null && http >= 400);

  // (5) APPROVED ROUTABLE TECHNICAL CASES (3.2). Each one is a documented contract case, not a
  // business outcome read from a failed call.
  // 5a. 3.2 single E8 400 discrimination rule, applied AS A STAGE: ERR_DOCUMENT_TYPE_NON_SUPPORTE
  //     -> 200 UNSUPPORTED_DOCUMENT_TYPE, every other E8 refusal -> ERROR (502
  //     EXTRACTION_SCHEMA_INVALID), NEVER a 200 REJECTED and never a missing-information loop.
  if (src === 'E8ValidateExtraction' && (http === 400 || incoming.valid === false)) {
    return hasUnsupportedCode() ? 'UNSUPPORTED_DOCUMENT_TYPE' : 'ERROR';
  }
  // 5b. LLM unreachable / timeout / 5xx after the bounded attempts -> ERROR (AI_EXTRACTION_ERROR).
  if (src === 'OllamaExtract' && receivedFailure) return 'ERROR';
  // 5c. E2 read: 404 is a client input error (3.2 line 175), any other failure is a technical fault.
  if (src === 'E2GetRequest') { if (http === 404) return 'REQUEST_NOT_FOUND'; if (receivedFailure) return 'ERROR'; }
  // 5d. E2 reconciliation read: same rule; the 409/5xx/timeout that triggered it is already logged
  //     by AdoptE2Reconcile and is never answered as a business outcome.
  if (src === 'E2ReconcileRequest') { if (http === 404) return 'REQUEST_NOT_FOUND'; if (receivedFailure) return 'ERROR'; }
  // 5e. E5 500 carrying a generation cause -> 200 GENERATION_FAILED with the cause copied verbatim
  //     (3.2 line 171). Reached on the 2nd and last E5 attempt (R2): the 1st one is recovered by
  //     PrepareE5Recovery -> IFRecoveryAllowed -> E4ReconcileValidate -> AdoptE4Recovery -> IFRecoveryValidated -> E5RetryGenerate.
  if (src === 'E5GenerateDocument' && (code === 'TEMPLATE_NOT_FOUND' || code === 'DOCUMENT_GENERATION_ERROR')) return 'GENERATION_FAILED';
  // 5f. E1 / E3 / E4 business statuses: 422 -> MISSING_INFORMATION (3.2 line 169), 400 -> REJECTED or
  //     INVALID_REQUEST depending on persistence and on the structural codes (3.2 lines 174/170).
  if ((src === 'E1CreateRequest' || src === 'E4ValidateRequest') && http === 422) return 'MISSING_INFORMATION';
  if (src === 'E1CreateRequest' && http === 400) return persistedRequestId() !== null ? 'REJECTED' : 'INVALID_REQUEST';
  if (src === 'E4ValidateRequest' && http === 400) return 'REJECTED';
  if (src === 'E3PatchRequest' && http === 400) return isStructuralRejection() ? 'INVALID_REQUEST' : (persistedRequestId() !== null ? 'REJECTED' : 'INVALID_REQUEST');
  // 5g. Verification stage: a served document is GENERATED, a failure is ERROR (404 -> INTERNAL_ERROR,
  //     6 rows 26/27). GENERATED is declared ONLY here, so only when E6 answered 200 (R3).
  if (src === 'E6VerifyDocument') {
    if (receivedFailure) return 'ERROR';
    return generationMetadataComplete(generationPayload()) ? 'GENERATED' : 'ERROR';
  }

  // (6) HARD TECHNICAL PRECEDENCE (C4). Reached only when no case of (5) applies: any remaining
  // transport failure or received 4xx/5xx is an ERROR. This guard is BEFORE the first read of the
  // business 'status' below, so a technical failure can never be reported as a 200 outcome.
  if (receivedFailure) return 'ERROR';

  // (7) BUSINESS ROUTING, only on a received 2xx.
  const persisted = pickString('status');
  if (persisted === 'REJECTED') return 'REJECTED';
  // 3.3 GENERATION_FAILED always carries a cause taken from the three technical codes; a FAILED state
  // without one is a technical fault, never a business outcome.
  if (persisted === 'FAILED' || persisted === 'GENERATION_FAILED') return verbatimCause() !== null ? 'GENERATION_FAILED' : 'ERROR';
  if (persisted === 'MISSING_INFORMATION' || code === 'MISSING_INFORMATION') return 'MISSING_INFORMATION';
  // A VALIDATED state reached without E5/E6 is a technical fault, never a success. R6 routes a
  // VALIDATED/DRAFT/FAILED resume read to SwitchE2Route output 1 -> E4ReconcileValidate -> E5,
  // so this line is only reached by a RECONCILIATION read (E2ReconcileRequest), which must not mutate.
  if (persisted === 'VALIDATED' || persisted === 'DRAFT') return 'ERROR';
  // A GENERATED state reached WITHOUT the E6 200 is never re-declared here (R3): it is handled in 5g.
  if (persisted === 'GENERATED') return 'ERROR';
  if (code === 'VALIDATION_ERROR') {
    if ((src === 'E1CreateRequest' || src === 'E3PatchRequest') && isStructuralRejection()) return 'INVALID_REQUEST';
    return persistedRequestId() !== null ? 'REJECTED' : 'INVALID_REQUEST';
  }
  if (incoming.valid === false) return 'ERROR';
  return 'ERROR';
};

// 3.4 bindings, applied in order of causality.
/* Structured technical log of an unhandled backend status (correlationId + stage + status, no PII, no backend body, never part of the egress envelope). A logging fault must never break the response. */ const audit = function (stage, status, detail) { try { if (typeof console !== 'undefined' && console && typeof console.log === 'function') { console.log(JSON.stringify({ log: 'document-generation.unhandled-backend-status', correlationId: correlationIdOf(), stage: stage, httpStatus: (status === null || status === undefined) ? null : status, detail: detail, awaitingE2Reconciliation: true })); } } catch (e) { /* logging is best effort */ } }; const resolveErrorCode = function (outcome) {
  if (outcome === 'INVALID_REQUEST') return 'VALIDATION_ERROR';
  if (outcome === 'REQUEST_NOT_FOUND') return 'REQUEST_NOT_FOUND';

  const orchestrator = orchestratorFailure();
  if (orchestrator !== null) return orchestrator;

  // An item authored by one of our own Code nodes carries its own approved code (C5 short-circuits).
  // It outranks every stage rule below: the stage HTTP nodes were never reached, so a stage-derived
  // code (ex. a backend-stage access failure) would be a misattribution.
  if (incoming.outcome === 'ERROR' && incoming.error !== null && typeof incoming.error === 'object'
      && typeof incoming.error.code === 'string' && APPROVED_ERROR_CODES.indexOf(incoming.error.code) !== -1) {
    return incoming.error.code;
  }

  // LLM unreachable / timeout / 5xx after the bounded attempts, or non-strict-JSON answer.
  if (src === 'OllamaExtract') return 'AI_EXTRACTION_ERROR';

  const status = httpStatus();
  // A genuine access failure is the only thing that means BACKEND_UNAVAILABLE (3.2 line 179: bounded
  // backend ACCESS failures on E1-E8). A RECEIVED 5xx is never 'backend down' (M2, 4 line 388).
  const accessFailure = isHttpErrorItem() && (status === null || status === 0);

  // E8: any deterministic 400 that is not the unsupported type -> EXTRACTION_SCHEMA_INVALID
  // (never AI_EXTRACTION_ERROR, which is reserved to LLM / parse failures); access failure -> 503.
  /* E8: a deterministic rejection that is not the unsupported type is EXTRACTION_SCHEMA_INVALID (never AI_EXTRACTION_ERROR, reserved to LLM/parse failures). A genuine access failure (error output with no status at all) is BACKEND_UNAVAILABLE; any other received status is logged and reported as INTERNAL_ERROR. */ if (src === 'E8ValidateExtraction') { if (status === 400 || incoming.valid === false) return 'EXTRACTION_SCHEMA_INVALID'; if (accessFailure) { audit(src, status, 'TRANSPORT_FAILURE'); return 'BACKEND_UNAVAILABLE'; } audit(src, status, 'UNHANDLED_BACKEND_STATUS'); return 'INTERNAL_ERROR'; }

  // E1-E6: a real access failure -> BACKEND_UNAVAILABLE (503); every RECEIVED status that is not
  // routed above -> INTERNAL_ERROR (500) + structured log awaiting E2 reconciliation (3.2 line 194,
  // 4 line 388). A received 500 DATABASE_ERROR (optimistic-locking conflict, finding F-I-3) is
  // therefore NEVER classified as backend down and never answers 503.
  if (BACKEND_STAGES.indexOf(src) !== -1) { if (accessFailure) { audit(src, status, 'TRANSPORT_FAILURE'); return 'BACKEND_UNAVAILABLE'; } audit(src, status, 'RECEIVED_STATUS_NOT_ROUTED'); return 'INTERNAL_ERROR'; }

  return 'INTERNAL_ERROR';
};

const correlationIdOf = function () {
  const fromBody = pickString('correlationId');
  if (fromBody !== null && CORRELATION_ID_RE.test(fromBody)) return fromBody;
  try {
    const init = $('InitOrchestration').first().json || {};
    if (typeof init.correlationId === 'string' && CORRELATION_ID_RE.test(init.correlationId)) return init.correlationId;
  } catch (e) {
    // no ingress item reachable
  }
  // Native UUID v4 generator (replaces require('crypto').randomUUID() which is not allowed in n8n Code nodes)
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.floor(Math.random() * 16);
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

// FR message authored by one of our own Code nodes (internalDetail proves it), never relayed from
// the backend.
const authoredMessage = function () {
  if (incoming.internalDetail === undefined) return null;
  if (incoming.error === null || typeof incoming.error !== 'object') return null;
  const message = incoming.error.message;
  return (typeof message === 'string' && message !== '') ? message : null;
};

const classified = classifyOutcome();
const outcome = APPROVED_OUTCOMES.indexOf(classified) === -1 ? 'ERROR' : classified;
const response = { outcome: outcome, correlationId: correlationIdOf() };

if (ERROR_OUTCOMES.indexOf(outcome) !== -1) {
  const code = resolveErrorCode(outcome);
  const authored = authoredMessage();
  response.error = {
    code: code,
    message: (outcome !== 'ERROR' && authored !== null) ? authored : (ERROR_MESSAGES[code] || ERROR_MESSAGES.INTERNAL_ERROR)
  };
}

if (outcome === 'GENERATED') {
  const generated = generationPayload();
  const envelope = nodeJson('E5GenerateDocument');
  // The selected documents[] entry may not repeat the envelope fields; the requestId and the status
  // then stay the ones of GenerateDocumentResponse (never recalculated here).
  const requestId = requestIdOf(generated) || requestIdOf(envelope) || persistedRequestId();
  if (requestId !== null) response.requestId = requestId;
  const generatedStatus = (typeof generated.status === 'string' && generated.status !== '') ? generated.status
    : ((typeof envelope.status === 'string' && envelope.status !== '') ? envelope.status : null);
  if (generatedStatus !== null) response.status = generatedStatus;
  if (typeof generated.documentId === 'string' && generated.documentId !== '') response.documentId = generated.documentId;
  if (typeof generated.fileName === 'string' && generated.fileName !== '') response.fileName = generated.fileName;
  if (typeof generated.downloadPath === 'string' && generated.downloadPath !== '') response.downloadPath = generated.downloadPath;
  if (typeof generated.generatedAt === 'string' && generated.generatedAt !== '') response.generatedAt = generated.generatedAt;
} else if (outcome === 'MISSING_INFORMATION') {
  const requestId = persistedRequestId();
  if (requestId !== null) response.requestId = requestId;
  const status = verbatimStatus();
  if (status !== null) response.status = status;
  const missing = pickArray('missingFields');
  if (missing !== null) response.missingFields = missing.slice();
