  if (cause === null || received5xx !== true || attemptsLeft !== true || requestId === null) {
    audit('REFUSED_' + String(cause === null ? 'NO_GENERATION_CAUSE' : (received5xx !== true ? 'NO_RECEIVED_5XX' : (attemptsLeft !== true ? 'ATTEMPT_BOUND_REACHED' : 'NO_REQUEST_ID'))));
