  return [{ json: incoming }];
}

/* AdoptE4Recovery: jonction de la garde E4 de REPRISE (3.3) et de la garde E4 de RECUPERATION (R2). ENTREE : RequestStatusResponse E4.
Sortie unique (C5) : la selection de branche est faite par le noeud routeur IFRecoveryValidated (statut VALIDATED et requestId de forme UUID -> E5RetryGenerate, SEUL cas autorise a appeler E5 depuis cette garde ; tout le reste -> FinalizeResponse, qui recopie le statut backend verbatim (3.3) : MISSING_INFORMATION, REJECTED, FAILED sans cause, ou un statut inconnu). Ce noeud ne teste lui-meme AUCUN statut (aucune branche morte) : il emet toujours l'item fusionne SANS marqueur, et le test VALIDATED + requestId UUID appartient entierement au routeur IFRecoveryValidated.
Le compteur e5Attempted est incremente ICI, juste avant l'appel E5 : c'est le seul endroit du workflow ou une tentative E5 est consommee, donc la borne R2 (2 au total) est verifiable sans execution et PrepareE5Recovery peut la relire. Aucun PATCH n'est emis : une reprise de lecture E2 peut appeler E4/E5, une reconciliation d'ambiguite, jamais (T14). */
const nodeExecuted = function (name) { try { return $(name).isExecuted === true; } catch (e) { return false; } };
const incoming = $input.first().json || {};
try {
  let ctx = {};
  try { ctx = $('MergeContext').first().json || {}; } catch (e) { ctx = {}; }
  const backend = incoming;
  const merged = Object.assign({}, ctx, backend);
  merged.correlationId = (typeof ctx.correlationId === 'string' && ctx.correlationId !== '') ? ctx.correlationId : null;
  merged.data = (ctx.data && typeof ctx.data === 'object') ? ctx.data : {};
  merged.backendData = (backend.data && typeof backend.data === 'object') ? backend.data : {};
