  let spent = 0;
  if (nodeExecuted('E5GenerateDocument')) spent = spent + 1;
  if (nodeExecuted('E5RetryGenerate')) spent = spent + 1;
  merged.e5Attempted = spent + 1;
  return [{ json: merged }];
} catch (e) {
  /* Une faute interne ne doit jamais repartir vers une generation : arret et classement. L'item de fault est emis SANS marqueur, donc le routeur IFRecoveryValidated le dirige sur sa sortie 1 (FinalizeResponse) : ce chemin est EQUIVALENT au chemin non-VALIDATED de la sortie principale, aucune branche n'est morte. */
  return [{ json: incoming }];
}
